#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Regenerates src/Http/GeneratedMethods.php with one fully-typed PHP method
 * per Telegram Bot API method (required fields as typed positional
 * parameters, optional fields as nullable named parameters defaulting to
 * null), so the whole API surface stays available with real signatures
 * instead of relying only on the generic TelegramClient::call(). Fields
 * whose type is a Telegram object (e.g. reply_markup, entities) are typed
 * against the classes/interfaces generated by tools/generate-types.php,
 * with a plain `array` alternative always available as a fallback.
 *
 * Source of truth: the community-maintained machine-readable spec at
 * https://github.com/davtur19/TuriBotGen, which tracks every official
 * Telegram Bot API release (the same source already used by the
 * bazzastyle/bazzabot package vendored elsewhere in this project).
 *
 * Run this whenever Telegram publishes a new Bot API version (together
 * with generate-types.php — see tools/generate-api.php to run both):
 *
 *   php tools/generate-methods.php
 *
 * It fully overwrites src/Http/GeneratedMethods.php — review the diff and
 * run the test suite before committing.
 */

require __DIR__ . '/lib/spec-support.php';

const OUTPUT_PATH = __DIR__ . '/../src/Http/GeneratedMethods.php';

/**
 * @param array<string, true> $abstractNames
 * @param array<string, true> $knownTypeNames
 * @param array<string, true> $usedTypeNames written to: class/interface names referenced, for the `use` block
 */
function generateMethod(stdClass $method, array $abstractNames, array $knownTypeNames, array &$usedTypeNames): string
{
    $required = [];
    $optional = [];
    foreach ($method->fields ?? [] as $field) {
        if ($field->optional) {
            $optional[] = $field;
        } else {
            $required[] = $field;
        }
    }

    $paramLines = [];
    $bodyLines = [];
    $docParamLines = [];

    $collect = function (stdClass $field, bool $optional) use (&$usedTypeNames, $abstractNames, $knownTypeNames): string {
        $type = mapFieldType($field->types, $abstractNames, $knownTypeNames);
        foreach (explode('|', $type) as $part) {
            if (isset($abstractNames[$part]) || isset($knownTypeNames[$part])) {
                $usedTypeNames[$part] = true;
            }
        }

        return nullableType($type, $optional);
    };

    foreach ($required as $field) {
        $type = $collect($field, false);
        $paramLines[] = "{$type} \${$field->name}";
        $bodyLines[] = "        \$args['{$field->name}'] = \${$field->name};";
        $docParamLines[] = "     * @param {$type} \${$field->name} " . wrapComment($field->description, '     *     ');
    }

    foreach ($optional as $field) {
        $type = $collect($field, true);
        $paramLines[] = "{$type} \${$field->name} = null";
        $bodyLines[] = "        if (\${$field->name} !== null) \$args['{$field->name}'] = \${$field->name};";
        $docParamLines[] = "     * @param {$type} \${$field->name} " . wrapComment($field->description, '     *     ') . ' (optional)';
    }

    $signature = $paramLines === []
        ? "public function {$method->name}(): TelegramResponse"
        : "public function {$method->name}(\n        " . implode(",\n        ", $paramLines) . ",\n    ): TelegramResponse";

    $body = $bodyLines === []
        ? "        return \$this->call(__FUNCTION__, []);"
        : "        \$args = [];\n" . implode("\n", $bodyLines) . "\n\n        return \$this->call(__FUNCTION__, \$args);";

    $docLines = array_merge(
        ['     * ' . wrapComment($method->description, '     * ')],
        ['     *'],
        ['     * @see https://core.telegram.org/bots/api#' . strtolower($method->name)],
        $docParamLines === [] ? [] : array_merge(['     *'], $docParamLines),
        ['     *'],
        ['     * @return TelegramResponse'],
    );

    return "    /**\n" . implode("\n", $docLines) . "\n     */\n    {$signature}\n    {\n{$body}\n    }\n";
}

$spec = fetchSpec();
$abstractNames = abstractTypeNames($spec);
$knownTypeNames = knownTypeNames($spec);

$usedTypeNames = [];
$methodBlocks = [];
foreach ($spec->methods as $method) {
    $methodBlocks[] = generateMethod($method, $abstractNames, $knownTypeNames, $usedTypeNames);
}

ksort($usedTypeNames);
$useLines = buildGroupedUseLines('Bazzastyle\\BazzaBot\\Types', array_keys($usedTypeNames));

$header = <<<PHP
<?php

declare(strict_types=1);

namespace Bazzastyle\\BazzaBot\\Http;

%%USE_LINES%%
/**
 * AUTO-GENERATED — DO NOT EDIT BY HAND.
 *
 * Generated by tools/generate-methods.php from the Telegram Bot API spec
 * (version {$spec->version}, see https://core.telegram.org/bots/api-changelog).
 * Regenerate with: php tools/generate-methods.php (or tools/generate-api.php
 * to refresh methods and types together).
 *
 * One typed method per Telegram Bot API method: required fields become
 * required positional parameters, optional fields become nullable named
 * parameters defaulting to null (and are omitted from the request unless
 * explicitly set). Every method delegates to TelegramClient::call(), which
 * applies rate limiting, retries and logging uniformly.
 */
trait GeneratedMethods
{
PHP;

// "%%USE_LINES%%" is a plain-text marker (not interpolated by the heredoc
// above), replaced here with the `use` statement for any Types class/
// interface actually referenced — empty when no method needs one.
$header = str_replace("%%USE_LINES%%\n", $useLines, $header);

$footer = "}\n";

$output = $header . "\n" . implode("\n", $methodBlocks) . $footer;

file_put_contents(OUTPUT_PATH, $output);

fwrite(STDOUT, sprintf(
    "Generated %d methods (%d referenced types) from Telegram Bot API spec v%s -> %s\n",
    count($spec->methods),
    count($usedTypeNames),
    $spec->version,
    OUTPUT_PATH,
));
